def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color = next((v for v in grid[0] if v != 0), None)
    if color is None:
        return out

    for apex, value in enumerate(grid[0]):
        if value != color:
            continue
        for r in range(1, h):
            left, right = apex - r, apex + r
            # Fill the interior of the expanding V, including portions clipped by the grid edge.
            start, end = max(0, left + 1), min(w - 1, right - 1)
            for c in range(start, end + 1):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
